#!/usr/bin/env python3
"""Regenerate the auto section of ENGINE_PROVENANCE.md from ENGINE_LOCK.json."""
import json, re
from datetime import datetime
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
lock = json.loads((ROOT / "ENGINE_LOCK.json").read_text())
rows = "\n".join(f"| {f} | {e['upstream_blob_sha']} | {e['upstream_sha256'][:16]}… | {e['vendored_sha256'][:16]}… |"
                 for f, e in sorted(lock["files"].items()))
sec = (f"<!-- BEGIN ENGINE_LOCK (generated by scripts/render_provenance.py; do not edit) -->\n"
       f"## Pinned engine\n- Source: `{lock['source_repo']}` @ **{lock['commit']}**, path `{lock['upstream_path']}`\n"
       f"- Vendored to `src/provebreak_culprit/_engine/` ({len(lock['files'])} files = import closure of `{lock['entry']}`)\n"
       f"- Transform: {lock['transform']}\n- Full hashes: `ENGINE_LOCK.json`; check with `python3 scripts/vendor_engine.py verify`\n"
       f"- Rendered {datetime.now().strftime('%Y-%m-%d %H:%M %Z').strip()}\n\n"
       f"| file | upstream git blob sha | upstream sha256 | vendored sha256 |\n|---|---|---|---|\n{rows}\n"
       f"<!-- END ENGINE_LOCK -->")
p = ROOT / "ENGINE_PROVENANCE.md"
t = p.read_text() if p.exists() else "# Engine provenance\n"
pat = re.compile(r"<!-- BEGIN ENGINE_LOCK.*?<!-- END ENGINE_LOCK -->", re.S)
t = pat.sub(lambda _: sec, t) if pat.search(t) else t.replace("\n", "\n\n" + sec + "\n", 1)
p.write_text(t)
# G4: machine-readable engine provenance for the package (outside the hash-locked _engine/ tree).
# Names the exact sentinel-lab commit; the upstream __version__ (e.g. "5.3.0") is deliberately NOT used.
prov = ROOT / "src" / "provebreak_culprit" / "_provenance.py"
prov.write_text(
    '"""GENERATED by scripts/render_provenance.py from ENGINE_LOCK.json (run by scripts/swap_engine.sh). Do not edit."""\n'
    f'ENGINE_SOURCE_REPO = {lock["source_repo"]!r}\n'
    f'ENGINE_COMMIT = {lock["commit"]!r}\n'
    f'ENGINE_ID = {(lock["source_repo"].split("/")[-1] + "@" + lock["commit"])!r}\n')
